package sqlite

// Preserve legacy EXECUTION plans; only an exact final formal source can admit
// an IMPLEMENTATION predecessor. The new successor remains EXECUTION-owned.
const runtimeSelectionFormalNoRunV104SQL = `
DROP TRIGGER no_run_successor_effect_owner;
CREATE TRIGGER no_run_successor_effect_owner BEFORE INSERT ON no_run_successor_effect_authorities
WHEN NOT EXISTS(SELECT 1 FROM tasks t JOIN execution_proposals predecessor ON predecessor.id=NEW.predecessor_execution_id JOIN execution_proposals successor ON successor.id=NEW.successor_execution_id JOIN execution_cancellations c ON c.project_id=NEW.effective_cancellation_project_id AND c.request_id=NEW.effective_cancellation_request_id JOIN runtime_scope_plans p ON p.plan_id=NEW.runtime_scope_plan_id JOIN runtime_preparation_authorities a ON a.plan_id=p.plan_id JOIN execution_proposal_admissions source_admission ON source_admission.proposal_id=predecessor.id AND source_admission.runtime_scope_plan_id=NEW.predecessor_runtime_scope_plan_id AND source_admission.runtime_preparation_authority_id=NEW.predecessor_runtime_scope_plan_id JOIN runtime_scope_plans source_plan ON source_plan.plan_id=source_admission.runtime_scope_plan_id JOIN runtime_preparation_authorities source_authority ON source_authority.plan_id=source_admission.runtime_preparation_authority_id
 WHERE t.id=NEW.task_id AND t.current_definition_revision_id=NEW.task_definition_revision_id AND predecessor.task_id=t.id AND predecessor.task_definition_revision_id=NEW.task_definition_revision_id AND predecessor.status='ADMITTED' AND predecessor.outcome='CANCELED' AND predecessor.run_id IS NULL AND successor.task_id=t.id AND successor.task_definition_revision_id=NEW.task_definition_revision_id AND successor.status='ADMITTED' AND successor.outcome='PENDING' AND successor.run_id IS NULL AND c.owner_type='EXECUTION' AND c.owner_id=predecessor.id AND c.state='CANCELED' AND c.backend_disposition='NO_BACKEND' AND c.interrupt_state='NOT_SENT' AND c.run_id IS NULL AND c.resolved_at IS NOT NULL AND source_plan.owner_id=predecessor.id AND source_authority.owner_kind=source_plan.owner_kind
 AND (source_plan.owner_kind='EXECUTION' OR (source_plan.owner_kind='IMPLEMENTATION' AND EXISTS(
 SELECT 1 FROM formal_execution_t2 f JOIN formal_execution_receipts r ON r.ai_session_id=f.ai_session_id AND r.request_id=f.request_id
 JOIN runtime_selection_sources s ON s.ai_session_id=f.ai_session_id AND s.request_id=f.request_id AND s.approval_request_id=f.request_id
 JOIN runtime_selection_bindings binding ON binding.source_id=s.source_id AND binding.project_id=t.project_id AND binding.task_id=t.id AND binding.revision_id=t.current_definition_revision_id AND binding.runtime_role='IMPLEMENTATION'
 JOIN runtime_platform_qualifications q ON q.qualification_id=binding.qualification_id AND q.generation=binding.qualification_generation
 WHERE f.execution_id=predecessor.id AND f.plan_id=source_plan.plan_id AND f.plan_hash=source_plan.content_hash AND r.preparation_authority_id=source_plan.plan_id AND s.task_id=t.id AND s.revision_id=t.current_definition_revision_id
 AND q.state IN ('CURRENT','SUPERSEDED') AND binding.authority_snapshot_hash=NEW.verified_current_authority_snapshot_hash AND binding.authority_snapshot_hash=source_plan.authority_snapshot_hash))) AND source_authority.owner_id=predecessor.id AND source_authority.disposition='CURRENT' AND source_plan.content_hash=NEW.predecessor_plan_content_hash AND source_plan.authority_snapshot_hash=NEW.predecessor_authority_snapshot_hash AND p.owner_kind='EXECUTION' AND p.owner_id=successor.id AND p.task_id=t.id AND p.authority_snapshot_hash=NEW.verified_current_authority_snapshot_hash AND a.owner_kind='EXECUTION' AND a.owner_id=successor.id AND a.disposition='CURRENT' AND NOT EXISTS(SELECT 1 FROM runs r WHERE r.execution_proposal_id=predecessor.id OR r.execution_proposal_id=successor.id) AND NOT EXISTS(SELECT 1 FROM runtime_preparation_attempts attempt WHERE attempt.plan_id=p.plan_id))
BEGIN SELECT RAISE(ABORT,'successor effect authority owner mismatch'); END;
`
